async function main(args) {
    const params = args.params;

    // 解析 video_list 参数
    let video_list;
    try {
        video_list = typeof params.video_list === 'string' ? JSON.parse(params.video_list) : params.video_list;
    } catch (e) {
        return { error: `解析 video_list 参数时出错: ${e.message}` };
    }

    // 保证 video_list 是数组类型
    if (!Array.isArray(video_list)) video_list = [video_list];

    // 获取其他必要参数
    const width = parseInt(params.width);
    const height = parseInt(params.height);
    const bgm_url = params.bgm;  // 改为直接用 string
    if (!bgm_url) return { error: "缺少 bgm 音频链接" };

    // 初始化结果数组
    const videos = [];
    const audios = [];
    let current_time = 0;

    // 视频持续时间单位为“微秒”
    const default_duration = 5_000_000;

    // 处理每个视频
    for (let idx = 0; idx < video_list.length; idx++) {
        try {
            const video_url = String(video_list[idx]);
            const end_time = current_time + default_duration;

            videos.push({
                video_url: video_url,
                width: width,
                height: height,
                start: current_time,
                end: end_time,
                duration: default_duration
            });

            current_time = end_time;
        } catch (e) {
            console.error(`处理第${idx}个视频时出错: ${e.message}`);
            continue;
        }
    }

    const audio_duration = video_list.length * default_duration;
    audios.push({
        audio_url: bgm_url,
        duration: audio_duration,
        start: 0,
        end: audio_duration
    });

    // 返回结果
    return {
        videos: JSON.stringify(videos),
        audios: JSON.stringify(audios),
        total_duration: audio_duration
    };
}
